import {photoCacheInfo,clearMirror} from './photo-cache.mjs';
import {sharedIndexProgress,sharedIndexLabel,formatSize} from './photo-tools.mjs';
import {PROVIDERS,providerById,fetchModels,pickModel,chat,keyStorageId,cleanKey} from './ai-providers.mjs';
export const APP_VERSION = '1.28.0';
export function indexCoverage(library) {
  const photos=library.photos().filter(photo=>photo.mediaType!=='video');
  const current=(map,photo)=>map?.[photo.id]?.version===photo.version;
  return {total:photos.length,visual:photos.filter(p=>current(library.meta.visuals,p)&&library.meta.visuals[p.id].model==='clip-base32-q8-v1').length,
    faces:photos.filter(p=>current(library.meta.indexes,p)).length,
    checksums:photos.filter(p=>current(library.meta.checksums,p)).length};
}
export function indexCoverageSummary(library) {
  const c=indexCoverage(library);
  if(!c.total)return 'Load photos to check AI coverage. Videos are not AI indexed.';
  const fmt=n=>n.toLocaleString();
  const photos=library.photos().filter(photo=>photo.mediaType!=='video');
  const current=(map,photo)=>map?.[photo.id]?.version===photo.version;
  const pending=photos.filter(photo=>!(current(library.meta.visuals,photo)&&current(library.meta.indexes,photo)&&current(library.meta.checksums,photo))).length;
  const verdict=pending?`Index pending for ${fmt(pending)} of ${fmt(c.total)} photos. It continues automatically while the app is open (battery permitting), or press Index selected folder / Index all pCloud photos.`:`Index complete for all ${fmt(c.total)} photos. ✓`;
  return `${verdict} AI search ${fmt(c.visual)} / ${fmt(c.total)} · faces & text ${fmt(c.faces)} / ${fmt(c.total)} · duplicate checksums ${fmt(c.checksums)} / ${fmt(c.total)}. Indexes are saved in pCloud and restored on any device, even after reinstalling. Counts confirm completed indexes per photo version, not recognition accuracy.`;
}
export function indexProgressSummary(library,now=Date.now()) {
  const coverage=sharedIndexProgress(library);const indexed=coverage.done;const photos=library.photos().filter(p=>p.mediaType!=='video');
  if(!coverage.total)return 'Load your photo library to see indexing progress.';
  const count=`${sharedIndexLabel(library)} AI search · ${(indexed/coverage.total*100).toFixed(1)}%. Samsung and Mac results share pCloud. Faces & text: ${sharedIndexLabel(library,'faces')}.`;
  const job=library.visualJob;
  let status=library.scanError?'Folder scan incomplete. Refresh before indexing.':library.visualStatusError?'Cannot read indexing status: '+library.visualStatusError:!job?'Checking indexing status…':job.running?'Running: '+(job.phase||'Starting')+'.':indexed===photos.length?'AI search complete for this folder.':job.message?'Indexing stopped: '+job.message:job.phase==='Paused'?'Indexing paused. Resume to process remaining photos.':'No AI search job is running here. Start or resume indexing; completed photos are skipped.';
  if(job?.running&&job.updatedAt&&now-job.updatedAt>180000)status+=' No step progress for '+Math.floor((now-job.updatedAt)/60000)+' minutes. Check the current step below; stop and resume if it stays stuck.';
  if(library.syncing)status+=' Restoring shared pCloud records…';
  if(library.cloudError)status+=' Cloud sync: '+library.cloudError;
  return count+' '+status;
}
